export const getGetExternalParlorSummaryUrl = (parlorCode: string,
    date: string,) => {




  return `/api/external/parlor-summary/${parlorCode}/${date}`
}

/**
 * @summary Get the external system's collection summary for a parlor and date
 */
export const getExternalParlorSummary = async (parlorCode: string,
    date: string, options?: RequestInit): Promise<ExternalSummary> => {

  return customFetch<ExternalSummary>(getGetExternalParlorSummaryUrl(parlorCode,date),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetExternalParlorSummaryQueryKey = (parlorCode: string,
    date: string,) => {
    return [
    `/api/external/parlor-summary/${parlorCode}/${date}`
    ] as const;
    }


export const getGetExternalParlorSummaryQueryOptions = <TData = Awaited<ReturnType<typeof getExternalParlorSummary>>, TError = ErrorType<ErrorResponse>>(parlorCode: string,
    date: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getExternalParlorSummary>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetExternalParlorSummaryQueryKey(parlorCode,date);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getExternalParlorSummary>>> = ({ signal }) => getExternalParlorSummary(parlorCode,date, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: !!(parlorCode && date), ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getExternalParlorSummary>>, TError, TData> & { queryKey: QueryKey }
}

export type GetExternalParlorSummaryQueryResult = NonNullable<Awaited<ReturnType<typeof getExternalParlorSummary>>>
export type GetExternalParlorSummaryQueryError = ErrorType<ErrorResponse>


/**
 * @summary Get the external system's collection summary for a parlor and date
 */

export function useGetExternalParlorSummary<TData = Awaited<ReturnType<typeof getExternalParlorSummary>>, TError = ErrorType<ErrorResponse>>(
 parlorCode: string,
    date: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getExternalParlorSummary>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetExternalParlorSummaryQueryOptions(parlorCode,date,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return { ...query, queryKey: queryOptions.queryKey };
}







